/**
 * Calculate late fee for an invoice: 0.04% per day of the amount due.
 * @param {{ status: string, dueDate?: string, lines: Array, payments?: Array }} invoice
 * @param {string} asOf - date in YYYY-MM-DD format
 * @returns {number} late fee in cents, or 0 if not overdue
 */
export function lateFee(invoice, asOf) {
  if (!invoice.dueDate || invoice.dueDate >= asOf) {
    return 0;
  }

  const daysOverdue = daysBetween(invoice.dueDate, asOf);
  const due = balanceDue(invoice);
  const fee = due * 0.0004 * daysOverdue;

  return roundCents(fee);
}

/**
 * Get a dashboard summary of invoice data.
 * @param {Array<{ status: string, customerId: string, dueDate?: string, lines: Array, payments?: Array }>} invoices
 * @param {string} asOf - date in YYYY-MM-DD format
 * @returns {{ counts: { draft: number, issued: number, partially_paid: number, paid: number }, outstanding: number, overdue: { count: number, amount: number }, topCustomers: Array<{ customerId: string, due: number }> }}
 */
export function dashboard(invoices, asOf) {
  // Count invoices by status
  const counts = {
    draft: 0,
    issued: 0,
    partially_paid: 0,
    paid: 0,
  };

  invoices.forEach((inv) => {
    counts[inv.status] = (counts[inv.status] ?? 0) + 1;
  });

  // Calculate outstanding (total due on issued and partially_paid)
  const outstanding = invoices
    .filter((inv) => inv.status === 'issued' || inv.status === 'partially_paid')
    .reduce((sum, inv) => sum + balanceDue(inv), 0);

  // Get overdue data
  const overdueList = overdueInvoices(invoices, asOf);
  const overdue = {
    count: overdueList.length,
    amount: overdueList.reduce((sum, inv) => sum + inv.due, 0),
  };

  // Get top 3 customers by amount due
  const customerDues = {};
  invoices
    .filter((inv) => inv.status === 'issued' || inv.status === 'partially_paid')
    .forEach((inv) => {
      const customerId = inv.customerId;
      const due = balanceDue(inv);
      customerDues[customerId] = (customerDues[customerId] ?? 0) + due;
    });

  const topCustomers = Object.entries(customerDues)
    .map(([customerId, due]) => ({ customerId, due }))
    .sort((a, b) => b.due - a.due)
    .slice(0, 3);

  return {
    counts,
    outstanding,
    overdue,
    topCustomers,
  };
}

